	('Q-esl-fast-beginner-1-38-001', 'esl-fast-beginner-1-38', 'How are Mr. Brown''s lectures?', 'Những bài giảng của thầy Brown như thế nào?', 'ACTIVE', NULL, NULL, NULL, NULL),
