	('Q-esl-fast-beginner-1-38-018', 'esl-fast-beginner-1-38', 'Does the student use his phone during class?', 'Cậu học sinh có sử dụng điện thoại trong giờ học không?', 'ACTIVE', NULL, NULL, NULL, NULL),
