INSERT INTO QUESTIONS (QUESTION_CODE, VOLUME_SLUG, QUESTION_TEXT, QUESTION_TEXT_VI, STATUS, CREATED_AT, UPDATED_AT, CREATED_BY, UPDATED_BY) VALUES
	/* (UUID(),'4000-essential-english-words-1-1','The lion and the rabbit','Sư tử và thỏ','4000_ESSENTIAL_ENGLISH_WORDS_1_1.mp3',NULL,'00:00:00.000','00:02:11.000','4000-essential-english-words-1',1,0,0,1), */
	('Q-4000-essential-english-words-1-1-001','4000-essential-english-words-1-1','What is the title of the story?','Tên của câu chuyện là gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-002','4000-essential-english-words-1-1','Where did the cruel lion live?','Con sư tử hung ác sống ở đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-003','4000-essential-english-words-1-1','What did the lion do every day?','Mỗi ngày sư tử làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-004','4000-essential-english-words-1-1','Why were the other animals afraid?','Tại sao các loài động vật khác sợ hãi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-005','4000-essential-english-words-1-1','What did the animals ask the lion to do?','Các loài động vật yêu cầu sư tử làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-006','4000-essential-english-words-1-1','What did the animals promise the lion?','Các loài động vật hứa điều gì với sư tử?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-007','4000-essential-english-words-1-1','How many animals did the lion agree to eat each day?','Sư tử đồng ý ăn bao nhiêu con vật mỗi ngày?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-008','4000-essential-english-words-1-1','Why did the animals make the deal with the lion?','Tại sao các loài động vật thỏa thuận với sư tử?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-009','4000-essential-english-words-1-1','What did the lion threaten to do if an animal did not come?','Sư tử đe dọa sẽ làm gì nếu một con vật không đến?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-010','4000-essential-english-words-1-1','What happened after the animals made the deal?','Điều gì xảy ra sau khi các loài động vật thỏa thuận?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-011','4000-essential-english-words-1-1','Why were the other animals safe after the deal?','Tại sao các loài động vật khác an toàn sau thỏa thuận?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-012','4000-essential-english-words-1-1','Whose turn was it finally to go to the lion?','Cuối cùng đến lượt con vật nào đi gặp sư tử?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-013','4000-essential-english-words-1-1','How did the rabbit travel to the lion that day?','Ngày hôm đó thỏ đi đến gặp sư tử như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-014','4000-essential-english-words-1-1','Why was the lion angry with the rabbit?','Tại sao sư tử tức giận với thỏ?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-015','4000-essential-english-words-1-1','What did the lion ask the rabbit?','Sư tử hỏi thỏ điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-016','4000-essential-english-words-1-1','What did the rabbit say he was hiding from?','Thỏ nói nó đang trốn khỏi ai?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-017','4000-essential-english-words-1-1','What did the other lion claim to be?','Con sư tử kia tự nhận mình là gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-018','4000-essential-english-words-1-1','Why did the rabbit say he was afraid?','Tại sao thỏ nói nó sợ hãi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-019','4000-essential-english-words-1-1','What did the lion say about himself?','Sư tử nói gì về chính mình?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-020','4000-essential-english-words-1-1','What did the lion want the rabbit to do?','Sư tử muốn thỏ làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-021','4000-essential-english-words-1-1','What did the rabbit offer to show the lion?','Thỏ đề nghị dẫn sư tử đi xem gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-022','4000-essential-english-words-1-1','Where did the rabbit lead the lion?','Thỏ dẫn sư tử đến đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-023','4000-essential-english-words-1-1','Where was the old well?','Cái giếng cũ ở đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-024','4000-essential-english-words-1-1','What was at the bottom of the well?','Có gì ở đáy giếng?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-025','4000-essential-english-words-1-1','What did the rabbit tell the lion to do?','Thỏ bảo sư tử làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-026','4000-essential-english-words-1-1','Where did the rabbit say the other lion lived?','Thỏ nói con sư tử kia sống ở đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-027','4000-essential-english-words-1-1','What did the lion see in the water?','Sư tử nhìn thấy gì trong nước?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-028','4000-essential-english-words-1-1','Whose face did the lion see in the water?','Sư tử nhìn thấy khuôn mặt của ai trong nước?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-029','4000-essential-english-words-1-1','Who did the lion think was in the well?','Sư tử nghĩ ai đang ở trong giếng?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-030','4000-essential-english-words-1-1','Why did the lion jump into the well?','Tại sao sư tử nhảy xuống giếng?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-031','4000-essential-english-words-1-1','What happened to the lion after he jumped into the well?','Điều gì xảy ra với sư tử sau khi nó nhảy xuống giếng?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-032','4000-essential-english-words-1-1','How did the other animals feel at the end?','Cuối cùng các loài động vật khác cảm thấy thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-033','4000-essential-english-words-1-1','Why were the animals pleased with the rabbit?','Tại sao các loài động vật hài lòng với thỏ?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-034','4000-essential-english-words-1-1','What kind of trick did the rabbit use?','Thỏ đã sử dụng mưu kế như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-035','4000-essential-english-words-1-1','What did the lion promise at the beginning of the deal?','Sư tử hứa điều gì khi bắt đầu thỏa thuận?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-036','4000-essential-english-words-1-1','What would happen if the animals did not send one animal each day?','Điều gì sẽ xảy ra nếu các loài vật không cử một con vật đến mỗi ngày?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-037','4000-essential-english-words-1-1','Why did the rabbit arrive late?','Tại sao thỏ đến muộn?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-038','4000-essential-english-words-1-1','What did the rabbit say about the other lion?','Thỏ nói gì về con sư tử kia?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-039','4000-essential-english-words-1-1','What did the lion want to do to the other lion?','Sư tử muốn làm gì với con sư tử kia?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-040','4000-essential-english-words-1-1','How did the rabbit get the lion to the well?','Thỏ đã đưa sư tử đến giếng bằng cách nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-041','4000-essential-english-words-1-1','What did the lion think the reflection was?','Sư tử nghĩ hình ảnh phản chiếu là gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-042','4000-essential-english-words-1-1','What did the lion do without waiting?','Sư tử đã làm gì mà không chờ đợi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-043','4000-essential-english-words-1-1','What was the result of the lion''s jump?','Kết quả việc sư tử nhảy xuống giếng là gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-044','4000-essential-english-words-1-1','Who created the plan that saved the animals?','Ai đã tạo ra kế hoạch cứu các loài động vật?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-045','4000-essential-english-words-1-1','Why did the lion agree to the animals'' plan?','Tại sao sư tử đồng ý với kế hoạch của các loài động vật?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-046','4000-essential-english-words-1-1','What did the animals want to avoid?','Các loài động vật muốn tránh điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-047','4000-essential-english-words-1-1','What made the lion believe there was another lion?','Điều gì khiến sư tử tin rằng có một con sư tử khác?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-048','4000-essential-english-words-1-1','What was the rabbit''s main advantage over the lion?','Lợi thế chính của thỏ so với sư tử là gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-049','4000-essential-english-words-1-1','What happened to all the other animals after the lion disappeared?','Điều gì xảy ra với tất cả các loài động vật khác sau khi sư tử biến mất?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-1-050','4000-essential-english-words-1-1','What lesson can be learned from the rabbit''s actions?','Có thể rút ra bài học gì từ hành động của thỏ?','ACTIVE',NULL,NULL,NULL,NULL),
	
	/* (UUID(),'4000-essential-english-words-1-2','The laboratory','Phòng thí nghiệm','4000_ESSENTIAL_ENGLISH_WORDS_1_2.mp3',NULL,'00:00:00.000','00:02:13.800','4000-essential-english-words-1',1,0,0,2), */
	('Q-4000-essential-english-words-1-2-001','4000-essential-english-words-1-2','What did Mia''s father have?','Bố của Mia có gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-2-002','4000-essential-english-words-1-2','What did Mia not know about the laboratory?','Mia không biết điều gì về phòng thí nghiệm?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-2-003','4000-essential-english-words-1-2','What did Mia''s father always do when he went into the laboratory?','Bố của Mia luôn làm gì khi ông đi vào phòng thí nghiệm?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-2-004','4000-essential-english-words-1-2','What did Mia know her father used the laboratory for?','Mia biết bố mình dùng phòng thí nghiệm để làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-2-005','4000-essential-english-words-1-2','Did Mia''s father tell her what his projects were?','Bố của Mia có nói cho cô bé biết những dự án của ông là gì không?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-2-006','4000-essential-english-words-1-2','When did Mia approach the laboratory door?','Khi nào Mia tiến đến cửa phòng thí nghiệm?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-2-007','4000-essential-english-words-1-2','What did Mia wonder about her father''s experiment?','Mia thắc mắc điều gì về thí nghiệm của bố?','ACTIVE',NULL,NULL,NULL,NULL),
