	('Q-4000-essential-english-words-1-5-044','Why did the jackal jump into the field of flowers?','Tại sao chó rừng nhảy vào cánh đồng hoa?','4000-essential-english-words-1-5',1,5,NULL,NULL,NULL,NULL),
