	('Q-4000-essential-english-words-1-5-046','What did the child do after falling from the jackal’s back?','Cô bé làm gì sau khi rơi khỏi lưng chó rừng?','4000-essential-english-words-1-5',1,5,NULL,NULL,NULL,NULL),
