	('Q-4000-essential-english-words-1-5-049','What is the main explanation given for the jackal’s black back?','Lời giải thích chính cho chiếc lưng đen của chó rừng là gì?','4000-essential-english-words-1-5',1,5,NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-5-050','What happened to the jackal ever since his experience with the sun child?','Điều gì xảy ra với chó rừng kể từ trải nghiệm với đứa trẻ mặt trời?','4000-essential-english-words-1-5',1,5,NULL,NULL,NULL,NULL);
	
