	('Q-4000-essential-english-words-1-9-028','4000-essential-english-words-1-9','What did the narrator ask the little girl?','Người kể chuyện đã hỏi cô bé điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-029','4000-essential-english-words-1-9','Did the little girl answer the narrator?','Cô bé có trả lời người kể chuyện không?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-030','4000-essential-english-words-1-9','What did the girl do instead of answering?','Thay vì trả lời, cô bé đã làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-031','4000-essential-english-words-1-9','What did the narrator say the girl could not do?','Người kể chuyện nói cô bé không thể làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-032','4000-essential-english-words-1-9','What did the girl admit she could not do?','Cô bé thừa nhận mình không thể làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-033','4000-essential-english-words-1-9','What did the girl say she could save?','Cô bé nói mình có thể cứu gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-034','4000-essential-english-words-1-9','How big was the starfish the girl picked up later?','Con sao biển mà cô bé nhặt sau đó lớn như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-035','4000-essential-english-words-1-9','What did the girl do after saying she could save the starfish?','Cô bé làm gì sau khi nói mình có thể cứu con sao biển?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-036','4000-essential-english-words-1-9','Where did the girl throw the starfish?','Cô bé ném con sao biển đi đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-037','4000-essential-english-words-1-9','How did the girl throw the starfish?','Cô bé đã ném con sao biển như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-038','4000-essential-english-words-1-9','What did the narrator listen to during his trip?','Người kể chuyện đã lắng nghe gì trong chuyến đi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-039','4000-essential-english-words-1-9','What kind of walk did the narrator take?','Người kể chuyện đã đi dạo như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-040','4000-essential-english-words-1-9','What did the narrator discover during the trip?','Người kể chuyện đã khám phá gì trong chuyến đi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-041','4000-essential-english-words-1-9','What did the narrator say about saving all the starfish?','Người kể chuyện nói gì về việc cứu tất cả sao biển?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-042','4000-essential-english-words-1-9','What emotion did the little girl experience before stopping crying?','Cô bé đã trải qua cảm xúc gì trước khi ngừng khóc?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-043','4000-essential-english-words-1-9','What did the narrator carefully avoid doing?','Người kể chuyện cẩn thận tránh làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-044','4000-essential-english-words-1-9','What did the little girl do after she stopped crying?','Cô bé làm gì sau khi ngừng khóc?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-045','4000-essential-english-words-1-9','Why did the little girl keep throwing starfish?','Tại sao cô bé tiếp tục ném những con sao biển?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-046','4000-essential-english-words-1-9','What did the narrator think about the number of starfish?','Người kể chuyện nghĩ gì về số lượng sao biển?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-047','4000-essential-english-words-1-9','What did the girl do after the narrator said she could not save them all?','Cô bé làm gì sau khi người kể chuyện nói cô không thể cứu tất cả?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-048','4000-essential-english-words-1-9','What did the girl smile before doing?','Cô bé mỉm cười trước khi làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-049','4000-essential-english-words-1-9','What lesson is suggested by the little girl''s actions?','Hành động của cô bé gợi ra bài học gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-9-050','4000-essential-english-words-1-9','What was the girl trying to do for the starfish?','Cô bé đang cố làm gì cho những con sao biển?','ACTIVE',NULL,NULL,NULL,NULL);
	
