INSERT INTO QUESTIONS (QUESTION_CODE, VOLUME_SLUG, QUESTION_TEXT, QUESTION_TEXT_VI, STATUS, CREATED_AT, UPDATED_AT, CREATED_BY, UPDATED_BY) VALUES
	('Q-4000-essential-english-words-1-30-001','4000-essential-english-words-1-30','What is the common idiom mentioned in the passage?','Thành ngữ phổ biến nào được đề cập trong bài đọc?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-002','4000-essential-english-words-1-30','What does "let the cat out of the bag" mean?','"Let the cat out of the bag" có nghĩa là gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-003','4000-essential-english-words-1-30','Where did the idiom come from?','Thành ngữ này bắt nguồn từ đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-004','4000-essential-english-words-1-30','What did people there do long ago?','Ngày xưa người dân ở đó đã làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-005','4000-essential-english-words-1-30','What did people sell from town to town?','Người dân bán gì từ thị trấn này sang thị trấn khác?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-006','4000-essential-english-words-1-30','What did the people believe strongly in?','Người dân rất coi trọng điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-007','4000-essential-english-words-1-30','What did the people not like doing?','Người dân không thích làm gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-008','4000-essential-english-words-1-30','Why did the man go to the center of the section?','Tại sao người đàn ông đến trung tâm của vùng đó?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-009','4000-essential-english-words-1-30','What did the man say he had for sale?','Người đàn ông nói anh ta có gì để bán?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-010','4000-essential-english-words-1-30','What did the man say about the price of the pig?','Người đàn ông nói gì về giá của con heo?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-011','4000-essential-english-words-1-30','How did the man hold the animal?','Người đàn ông cầm con vật như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-012','4000-essential-english-words-1-30','How was the man different from honest people?','Người đàn ông khác với những người trung thực như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-013','4000-essential-english-words-1-30','What was the man a master of?','Người đàn ông là bậc thầy về điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-014','4000-essential-english-words-1-30','What was the woman''s name?','Người phụ nữ tên là gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-015','4000-essential-english-words-1-30','What did Beth do when she saw the pig?','Beth đã làm gì khi nhìn thấy con heo?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-016','4000-essential-english-words-1-30','How much did the man offer the pig for?','Người đàn ông đề nghị bán con heo với giá bao nhiêu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-017','4000-essential-english-words-1-30','How did Beth react to the price?','Beth phản ứng thế nào với mức giá?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-018','4000-essential-english-words-1-30','What did Beth give the man?','Beth đưa cho người đàn ông thứ gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-019','4000-essential-english-words-1-30','Where did the man put the coin?','Người đàn ông bỏ đồng tiền vào đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-020','4000-essential-english-words-1-30','Why did the man walk ahead of Beth?','Tại sao người đàn ông đi trước Beth?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-021','4000-essential-english-words-1-30','What did the man give Beth?','Người đàn ông đưa cho Beth thứ gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-022','4000-essential-english-words-1-30','What did the man say was inside the bag?','Người đàn ông nói có gì bên trong chiếc túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-023','4000-essential-english-words-1-30','How did the man leave after giving Beth the bag?','Người đàn ông rời đi như thế nào sau khi đưa Beth chiếc túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-024','4000-essential-english-words-1-30','What did Beth notice about the bag?','Beth nhận thấy điều gì về chiếc túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-025','4000-essential-english-words-1-30','What did Beth think was inside the moving bag?','Beth nghĩ có gì bên trong chiếc túi đang chuyển động?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-026','4000-essential-english-words-1-30','Why did Beth open the bag?','Tại sao Beth mở chiếc túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-027','4000-essential-english-words-1-30','What was actually inside the bag?','Thực sự có gì bên trong chiếc túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-028','4000-essential-english-words-1-30','What did Beth say after discovering the cat?','Beth nói gì sau khi phát hiện con mèo?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-029','4000-essential-english-words-1-30','Why did the man return later?','Tại sao sau đó người đàn ông quay lại?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-030','4000-essential-english-words-1-30','What happened when Beth saw the man again?','Điều gì xảy ra khi Beth nhìn thấy người đàn ông lần nữa?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-031','4000-essential-english-words-1-30','Who did Beth tell about the man?','Beth kể cho ai về người đàn ông?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-032','4000-essential-english-words-1-30','What did Beth''s friends do to the man?','Bạn bè của Beth đã làm gì với người đàn ông?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-033','4000-essential-english-words-1-30','What did nobody know after stopping the man?','Sau khi chặn người đàn ông lại, không ai biết điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-034','4000-essential-english-words-1-30','What kind of person did someone say they needed?','Một người nói rằng họ cần một người như thế nào?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-035','4000-essential-english-words-1-30','Where did they go to solve the problem?','Họ đi đâu để giải quyết vấn đề?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-036','4000-essential-english-words-1-30','What did Beth tell the judge about?','Beth kể cho quan tòa nghe về điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-037','4000-essential-english-words-1-30','What did the judge ask Beth for?','Quan tòa yêu cầu Beth đưa ra điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-038','4000-essential-english-words-1-30','What did the judge ask Beth to demonstrate?','Quan tòa yêu cầu Beth chứng minh điều gì?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-039','4000-essential-english-words-1-30','What did Beth tell the judge to look in?','Beth bảo quan tòa nhìn vào đâu?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-040','4000-essential-english-words-1-30','What did Beth do with the bag?','Beth đã làm gì với chiếc túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-041','4000-essential-english-words-1-30','What came out of the bag?','Thứ gì đã chui ra khỏi chiếc túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-042','4000-essential-english-words-1-30','What did they learn about the man?','Họ biết được điều gì về người đàn ông?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-043','4000-essential-english-words-1-30','What happened to the man after they learned his secret?','Điều gì xảy ra với người đàn ông sau khi họ biết bí mật của anh ta?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-044','4000-essential-english-words-1-30','What does the idiom refer to in the story?','Thành ngữ này ám chỉ điều gì trong câu chuyện?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-045','4000-essential-english-words-1-30','Who discovered that there was a cat in the bag?','Ai phát hiện có một con mèo trong túi?','ACTIVE',NULL,NULL,NULL,NULL),
	('Q-4000-essential-english-words-1-30-046','4000-essential-english-words-1-30','Why did Beth tell her friends about the man?','Tại sao Beth kể cho bạn bè về người đàn ông?','ACTIVE',NULL,NULL,NULL,NULL),
